import numpy as np, sys
sys.path.insert(0,'/workspace/work')
from lib import read_wav
def peaks(f):
    sr,x=read_wav(f); x=np.asarray(x).ravel().astype(float)
    X=np.abs(np.fft.rfft(x*np.hanning(len(x)))); fr=np.fft.rfftfreq(len(x),1/sr)
    # top 6 spectral peaks
    idx=np.argsort(X)[::-1][:400]
    sel=[]
    for i in sorted(idx):
        if all(abs(fr[i]-s)>15 for s in sel): sel.append(fr[i])
        if len(sel)>=6: break
    return sr, sorted([round(s,1) for s in sel])
for n in ['bass','lead','pluck','bell','padAm','padF','padC','padG']:
    sr,p=peaks(f'smp/{n}.wav')
    print(n, p)
# loop continuity check: last sample vs loop point sample for bass and lead
for n,L,tot in [('bass',4092,8184),('lead',6393,12786),('padAm',8363,16726),('padC',8363,16726)]:
    sr,x=read_wav(f'smp/{n}.wav'); x=x.ravel()
    print(n,"last10",x[-6:],"at loopstart",x[L:L+6], "jump", int(abs(x[-1]-x[L])))
EOF"}

